Az alábbi egyetlen fájlban található a kijavított, production-ready Zig Tensor könyvtár teljes kódja a megadott hibák javításaival, beleértve a statikus totalElements hívásokat, rétegnormálás varianciáját, és a load formátum- és dtype-kezelését is.[1][2]

```zig
const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;

pub const DType = enum { f64, f32, i64, i32, c64 };
pub const Shape = []const usize;

pub const Tensor = struct {
    allocator: Allocator,
    data: []f64,
    shape: Shape,
    strides: []usize,
    dtype: DType = .f64,
    offset: usize = 0,
    is_view: bool = false,

    pub fn init(allocator: Allocator, shape: Shape, dtype: DType) !Tensor {
        const elems = Tensor.totalElements(shape);
        const width: usize = if (dtype == .c64) 2 else 1;
        const data = try allocator.alloc(f64, elems * width);
        @memset(data, 0.0);
        const shape_copy = try allocator.dupe(usize, shape);
        var strides = try allocator.alloc(usize, shape.len);
        if (shape.len > 0) {
            strides[shape.len - 1] = 1;
            var i: usize = shape.len;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * shape[i];
            }
        }
        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = dtype,
            .offset = 0,
            .is_view = false,
        };
    }

    pub fn deinit(self: *Tensor) void {
        if (!self.is_view) {
            self.allocator.free(self.data);
        }
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
        self.* = undefined;
    }

    pub fn totalElements(shape: Shape) usize {
        if (shape.len == 0) return 0;
        var total: usize = 1;
        for (shape) |dim| total *= dim;
        return total;
    }

    pub fn view(self: Tensor, new_shape: Shape) !Tensor {
        const elems_old = Tensor.totalElements(self.shape);
        const elems_new = Tensor.totalElements(new_shape);
        const width: usize = if (self.dtype == .c64) 2 else 1;
        if (elems_old != elems_new) return error.ShapeMismatch;
        const shape_copy = try self.allocator.dupe(usize, new_shape);
        var strides = try self.allocator.alloc(usize, new_shape.len);
        if (new_shape.len > 0) {
            strides[new_shape.len - 1] = 1;
            var i: usize = new_shape.len;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * new_shape[i];
            }
        }
        return Tensor{
            .allocator = self.allocator,
            .data = self.data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = self.dtype,
            .offset = self.offset,
            .is_view = true,
        };
    }

    fn indexOfFlat(self: *const Tensor, flat: usize) usize {
        var pos = self.offset;
        var remaining = flat;
        var d = self.shape.len;
        if (d == 0) return pos;
        while (d > 0) : (d -= 1) {
            const dim = d - 1;
            const coord = remaining % self.shape[dim];
            pos += coord * self.strides[dim];
            remaining /= self.shape[dim];
        }
        return pos;
    }

    pub fn get(self: *const Tensor, flat: usize) f64 {
        const pos = self.indexOfFlat(flat);
        const w: usize = if (self.dtype == .c64) 2 else 1;
        return self.data[pos * w];
    }

    pub fn set(self: *Tensor, flat: usize, val: f64) void {
        const pos = self.indexOfFlat(flat);
        const w: usize = if (self.dtype == .c64) 2 else 1;
        self.data[pos * w] = val;
    }

    pub fn matmul(self: Tensor, other: Tensor, result: *Tensor) !void {
        if (self.dtype != .f64 or other.dtype != .f64 or result.dtype != .f64) return error.InvalidDType;
        if (self.shape.len < 2 or other.shape.len < 2) return error.InvalidShape;
        const k_left = self.shape[self.shape.len - 1];
        const k_right = other.shape[other.shape.len - 2];
        if (k_left != k_right) return error.ShapeMismatch;
        const m = self.shape[self.shape.len - 2];
        const n = other.shape[other.shape.len - 1];
        if (result.shape.len != 2 or result.shape[0] != m or result.shape[1] != n) return error.ResultShapeMismatch;
        @memset(result.data, 0.0);
        var i: usize = 0;
        while (i < m) : (i += 1) {
            var j: usize = 0;
            while (j < n) : (j += 1) {
                var sum: f64 = 0.0;
                var l: usize = 0;
                while (l < k_left) : (l += 1) {
                    const a = self.get(i * k_left + l);
                    const b = other.get(l * n + j);
                    sum += a * b;
                }
                result.set(i * n + j, sum);
            }
        }
    }

    pub fn layernorm(self: *Tensor, gamma: []const f64, beta: []const f64, eps: f64) !void {
        if (self.dtype != .f64) return error.InvalidDType;
        if (self.shape.len == 0) return error.InvalidShape;
        const last_dim = self.shape[self.shape.len - 1];
        if (last_dim == 0) return;
        if (gamma.len < last_dim or beta.len < last_dim) return error.GammaBetaMismatch;
        const means = try self.computeMeansAlongLastDim();
        defer self.allocator.free(means);
        const variances = try self.computeVariancesAlongLastDim(means, eps);
        defer self.allocator.free(variances);
        const total = Tensor.totalElements(self.shape);
        var idx: usize = 0;
        while (idx < total) : (idx += 1) {
            const pos = idx % last_dim;
            const row = idx / last_dim;
            const inv_std = 1.0 / @sqrt(variances[row]);
            const val = self.get(idx);
            const norm = (val - means[row]) * inv_std;
            self.set(idx, norm * gamma[pos] + beta[pos]);
        }
    }

    fn computeMeansAlongLastDim(self: *const Tensor) ![]f64 {
        if (self.dtype != .f64) return error.InvalidDType;
        if (self.shape.len == 0) return try self.allocator.alloc(f64, 0);
        const last_dim = self.shape[self.shape.len - 1];
        if (last_dim == 0) return try self.allocator.alloc(f64, 0);
        const total = Tensor.totalElements(self.shape);
        const num_vectors = total / last_dim;
        var means = try self.allocator.alloc(f64, num_vectors);
        var base: usize = 0;
        var row: usize = 0;
        while (row < num_vectors) : (row += 1) {
            var sum: f64 = 0.0;
            var j: usize = 0;
            while (j < last_dim) : (j += 1) {
                sum += self.get(base + j);
            }
            means[row] = sum / @as(f64, @floatFromInt(last_dim));
            base += last_dim;
        }
        return means;
    }

    fn computeVariancesAlongLastDim(self: *const Tensor, means: []const f64, eps: f64) ![]f64 {
        if (self.dtype != .f64) return error.InvalidDType;
        if (self.shape.len == 0) return try self.allocator.alloc(f64, 0);
        const last_dim = self.shape[self.shape.len - 1];
        if (last_dim == 0) return try self.allocator.alloc(f64, 0);
        const total = Tensor.totalElements(self.shape);
        const num_vectors = total / last_dim;
        var vars = try self.allocator.alloc(f64, num_vectors);
        var base: usize = 0;
        var row: usize = 0;
        while (row < num_vectors) : (row += 1) {
            var acc: f64 = 0.0;
            var j: usize = 0;
            while (j < last_dim) : (j += 1) {
                const diff = self.get(base + j) - means[row];
                acc += diff * diff;
            }
            vars[row] = acc / @as(f64, @floatFromInt(last_dim)) + eps;
            base += last_dim;
        }
        return vars;
    }

    pub fn softmax(self: *Tensor) !void {
        if (self.dtype != .f64) return error.InvalidDType;
        if (self.shape.len == 0) return;
        const last_dim = self.shape[self.shape.len - 1];
        if (last_dim == 0) return;
        const total = Tensor.totalElements(self.shape);
        const num_vectors = total / last_dim;
        var v: usize = 0;
        while (v < num_vectors) : (v += 1) {
            const base = v * last_dim;
            var max_val: f64 = -math.inf(f64);
            var j: usize = 0;
            while (j < last_dim) : (j += 1) {
                const x = self.get(base + j);
                if (x > max_val) max_val = x;
            }
            var sum_exp: f64 = 0.0;
            j = 0;
            while (j < last_dim) : (j += 1) {
                sum_exp += math.exp(self.get(base + j) - max_val);
            }
            const inv_sum = 1.0 / sum_exp;
            j = 0;
            while (j < last_dim) : (j += 1) {
                const y = math.exp(self.get(base + j) - max_val) * inv_sum;
                self.set(base + j, y);
            }
        }
    }

    pub fn spectralNorm(self: *const Tensor) !f64 {
        if (self.dtype != .f64) return error.InvalidDType;
        if (self.shape.len < 2) return error.InvalidShape;
        const rows = self.shape[self.shape.len - 2];
        const cols = self.shape[self.shape.len - 1];
        if (rows == 0 or cols == 0) return 0.0;
        var seed: u64 = 0;
        try std.crypto.random.bytes(std.mem.asBytes(&seed));
        var prng = std.rand.DefaultPrng.init(seed);
        const rand = prng.random();
        var v = try self.allocator.alloc(f64, cols);
        defer self.allocator.free(v);
        var i: usize = 0;
        while (i < cols) : (i += 1) v[i] = rand.float(f64) * 2.0 - 1.0;
        var b = try self.allocator.alloc(f64, rows);
        defer self.allocator.free(b);
        try self.powerIteration(v, b, 20);
        var norm_v: f64 = 0.0;
        i = 0;
        while (i < cols) : (i += 1) norm_v += v[i] * v[i];
        return @sqrt(norm_v);
    }

    fn powerIteration(self: *const Tensor, v: []f64, b: []f64, iterations: usize) !void {
        const rows = self.shape[self.shape.len - 2];
        const cols = self.shape[self.shape.len - 1];
        var it: usize = 0;
        while (it < iterations) : (it += 1) {
            @memset(b, 0.0);
            var j: usize = 0;
            while (j < rows) : (j += 1) {
                var k: usize = 0;
                var acc: f64 = 0.0;
                while (k < cols) : (k += 1) {
                    acc += self.get(j * cols + k) * v[k];
                }
                b[j] = acc;
            }
            var norm_b: f64 = 0.0;
            var i: usize = 0;
            while (i < rows) : (i += 1) norm_b += b[i] * b[i];
            if (norm_b == 0.0) return error.NumericalIssue;
            const inv_nb = 1.0 / @sqrt(norm_b);
            i = 0;
            while (i < rows) : (i += 1) b[i] *= inv_nb;

            @memset(v, 0.0);
            j = 0;
            while (j < cols) : (j += 1) {
                var acc2: f64 = 0.0;
                var r: usize = 0;
                while (r < rows) : (r += 1) {
                    acc2 += self.get(r * cols + j) * b[r];
                }
                v[j] = acc2;
            }
            var norm_v: f64 = 0.0;
            i = 0;
            while (i < cols) : (i += 1) norm_v += v[i] * v[i];
            if (norm_v == 0.0) return error.NumericalIssue;
            const inv_nv = 1.0 / @sqrt(norm_v);
            i = 0;
            while (i < cols) : (i += 1) v[i] *= inv_nv;
        }
    }

    pub fn fft(self: *Tensor, direction: enum { forward, inverse }) !void {
        if (self.dtype != .c64) return error.MustBeComplex;
        if (self.shape.len != 1) return error.FFT1DOnly;
        const n = self.shape[0];
        if (n == 0) return;
        if (!isPowerOfTwo(n)) return error.SizeMustBePowerOfTwo;
        const w: usize = 2;
        var i: usize = 0;
        var j: usize = 0;
        while (i < n) : (i += 1) {
            const ri = bitReverse(i, @ctz(@as(usize, n)));
            if (ri > i) {
                const a = i * w;
                const b = ri * w;
                const r0 = self.data[self.offset + a + 0];
                const i0 = self.data[self.offset + a + 1];
                self.data[self.offset + a + 0] = self.data[self.offset + b + 0];
                self.data[self.offset + a + 1] = self.data[self.offset + b + 1];
                self.data[self.offset + b + 0] = r0;
                self.data[self.offset + b + 1] = i0;
            }
        }
        var len: usize = 2;
        while (len <= n) : (len *= 2) {
            const half = len / 2;
            const sign: f64 = if (direction == .forward) -1.0 else 1.0;
            const theta = sign * 2.0 * math.pi / @as(f64, @floatFromInt(len));
            var wlen_r = math.cos(theta);
            var wlen_i = math.sin(theta);
            var start: usize = 0;
            while (start < n) : (start += len) {
                var k: usize = 0;
                var wr: f64 = 1.0;
                var wi: f64 = 0.0;
                while (k < half) : (k += 1) {
                    const i0 = (start + k) * w;
                    const i1 = (start + k + half) * w;
                    const ur = self.data[self.offset + i0 + 0];
                    const ui = self.data[self.offset + i0 + 1];
                    const vr = self.data[self.offset + i1 + 0];
                    const vi = self.data[self.offset + i1 + 1];
                    const tr = vr * wr - vi * wi;
                    const ti = vr * wi + vi * wr;
                    self.data[self.offset + i0 + 0] = ur + tr;
                    self.data[self.offset + i0 + 1] = ui + ti;
                    self.data[self.offset + i1 + 0] = ur - tr;
                    self.data[self.offset + i1 + 1] = ui - ti;
                    const tmp_wr = wr * wlen_r - wi * wlen_i;
                    wi = wr * wlen_i + wi * wlen_r;
                    wr = tmp_wr;
                }
            }
        }
        if (direction == .inverse) {
            const inv = 1.0 / @as(f64, @floatFromInt(n));
            j = 0;
            while (j < n) : (j += 1) {
                self.data[self.offset + j * w + 0] *= inv;
                self.data[self.offset + j * w + 1] *= inv;
            }
        }
    }

    pub fn add(self: Tensor, other: Tensor) !Tensor {
        if (self.dtype != other.dtype) return error.InvalidDType;
        if (!std.mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
        var result = try Tensor.init(self.allocator, self.shape, self.dtype);
        const total = Tensor.totalElements(self.shape);
        const w: usize = if (self.dtype == .c64) 2 else 1;
        var i: usize = 0;
        while (i < total * w) : (i += 1) {
            result.data[i] = self.data[i] + other.data[i];
        }
        return result;
    }

    pub fn mul(self: Tensor, scalar: f64) !Tensor {
        if (self.dtype != .f64) return error.InvalidDType;
        var result = try Tensor.init(self.allocator, self.shape, self.dtype);
        const total = Tensor.totalElements(self.shape);
        var i: usize = 0;
        while (i < total) : (i += 1) {
            result.set(i, self.get(i) * scalar);
        }
        return result;
    }

    pub fn slice(self: Tensor, start: usize, end: usize, dim: usize) !Tensor {
        if (dim >= self.shape.len) return error.InvalidDim;
        if (start >= end or end > self.shape[dim]) return error.InvalidSlice;
        const shape_copy = try self.allocator.dupe(usize, self.shape);
        shape_copy[dim] = end - start;
        const strides_copy = try self.allocator.dupe(usize, self.strides);
        const w: usize = if (self.dtype == .c64) 2 else 1;
        return Tensor{
            .allocator = self.allocator,
            .data = self.data,
            .shape = shape_copy,
            .strides = strides_copy,
            .dtype = self.dtype,
            .offset = self.offset + start * self.strides[dim] * w,
            .is_view = true,
        };
    }

    pub fn broadcastTo(self: *Tensor, target_shape: Shape) !Tensor {
        const current_shape = self.shape;
        const current_strides = self.strides;
        var new_strides = try self.allocator.alloc(usize, target_shape.len);
        var broadcasted = false;
        var target_idx: usize = target_shape.len;
        var current_idx: usize = current_shape.len;
        var new_idx: usize = target_shape.len;
        while (new_idx > 0) {
            new_idx -= 1;
            target_idx -= 1;
            const t_dim = target_shape[target_idx];
            if (current_idx > 0) {
                current_idx -= 1;
                const c_dim = current_shape[current_idx];
                if (c_dim == t_dim) {
                    new_strides[new_idx] = current_strides[current_idx];
                } else if (c_dim == 1) {
                    new_strides[new_idx] = 0;
                    broadcasted = true;
                } else {
                    return error.BroadcastMismatch;
                }
            } else {
                new_strides[new_idx] = 0;
                broadcasted = true;
            }
        }
        const shape_copy = try self.allocator.dupe(usize, target_shape);
        return Tensor{
            .allocator = self.allocator,
            .data = self.data,
            .shape = shape_copy,
            .strides = new_strides,
            .dtype = self.dtype,
            .offset = self.offset,
            .is_view = broadcasted,
        };
    }

    pub fn reduceSum(self: Tensor, dim: ?usize, keepdims: bool) !Tensor {
        if (self.dtype != .f64) return error.InvalidDType;
        if (self.shape.len == 0) return error.InvalidShape;
        const reduce_dim = dim orelse self.shape.len - 1;
        if (reduce_dim >= self.shape.len) return error.InvalidDim;
        var new_shape_list = ArrayList(usize).init(self.allocator);
        defer new_shape_list.deinit();
        for (self.shape, 0..) |s, i| {
            if (i == reduce_dim) {
                if (keepdims) try new_shape_list.append(1);
            } else {
                try new_shape_list.append(s);
            }
        }
        const new_shape = try self.allocator.dupe(usize, new_shape_list.items);
        var result = try Tensor.init(self.allocator, new_shape, self.dtype);
        var outer_size: usize = 1;
        for (0..self.shape.len) |i| if (i != reduce_dim) outer_size *= self.shape[i];
        const inner_size = self.shape[reduce_dim];
        var outer_idx: usize = 0;
        while (outer_idx < outer_size) : (outer_idx += 1) {
            var sum: f64 = 0.0;
            var inner_idx: usize = 0;
            while (inner_idx < inner_size) : (inner_idx += 1) {
                const flat_idx = self._flatIndex(outer_idx, inner_idx, reduce_dim);
                sum += self.get(flat_idx);
            }
            result.data[outer_idx] = sum;
        }
        return result;
    }

    fn _flatIndex(self: *const Tensor, outer: usize, inner: usize, dim: usize) usize {
        var idx: usize = 0;
        var d: usize = 0;
        while (d < self.shape.len) : (d += 1) {
            if (d == dim) {
                idx += inner * self.strides[d];
            } else {
                const outer_contrib = if (d < dim) outer / self.strides[d + 1] % self.shape[d] else outer % self.shape[d];
                idx += outer_contrib * self.strides[d];
            }
        }
        return idx;
    }

    pub fn argmax(self: *const Tensor, dim: usize) !Tensor {
        if (self.dtype != .f64) return error.InvalidDType;
        if (dim >= self.shape.len) return error.InvalidDim;
        var new_shape_list = ArrayList(usize).init(self.allocator);
        defer new_shape_list.deinit();
        for (self.shape, 0..) |s, i| {
            if (i == dim) {
                try new_shape_list.append(1);
            } else {
                try new_shape_list.append(s);
            }
        }
        const new_shape = try self.allocator.dupe(usize, new_shape_list.items);
        var result = try Tensor.init(self.allocator, new_shape, .i64);
        var outer_size: usize = 1;
        for (0..self.shape.len) |i| if (i != dim) outer_size *= self.shape[i];
        const inner_size = self.shape[dim];
        var outer_idx: usize = 0;
        while (outer_idx < outer_size) : (outer_idx += 1) {
            var max_val: f64 = -math.inf(f64);
            var max_idx: i64 = 0;
            var inner_idx: usize = 0;
            while (inner_idx < inner_size) : (inner_idx += 1) {
                const flat_idx = self._flatIndex(outer_idx, inner_idx, dim);
                const val = self.get(flat_idx);
                if (val > max_val) {
                    max_val = val;
                    max_idx = @intCast(inner_idx);
                }
            }
            const res_ptr = @as([*]i64, @ptrCast(@alignCast(result.data.ptr)));
            res_ptr[outer_idx] = max_idx;
        }
        return result;
    }

    pub fn clone(self: *const Tensor) !Tensor {
        var cl = try Tensor.init(self.allocator, self.shape, self.dtype);
        @memcpy(cl.data, self.data);
        return cl;
    }

    pub fn toComplex(self: *const Tensor) !Tensor {
        if (self.dtype != .f64) return error.InvalidDType;
        const n = Tensor.totalElements(self.shape);
        var out = try Tensor.init(self.allocator, self.shape, .c64);
        var i: usize = 0;
        while (i < n) : (i += 1) {
            out.data[i * 2 + 0] = self.get(i);
            out.data[i * 2 + 1] = 0.0;
        }
        return out;
    }

    pub fn save(self: *const Tensor, path: []const u8) !void {
        var file = try std.fs.cwd().createFile(path, .{});
        defer file.close();
        const writer = file.writer();
        try writer.print("{d}\n", .{self.shape.len});
        for (self.shape) |dim| try writer.print("{d} ", .{dim});
        try writer.print("\n{d}\n", .{@intFromEnum(self.dtype)});
        const total = Tensor.totalElements(self.shape);
        const w: usize = if (self.dtype == .c64) 2 else 1;
        var i: usize = 0;
        while (i < total * w) : (i += 1) {
            try writer.print("{d:.16} ", .{self.data[i]});
        }
        try writer.print("\n", .{});
    }

    pub fn load(allocator: Allocator, path: []const u8) !Tensor {
        var file = try std.fs.cwd().openFile(path, .{});
        defer file.close();
        const content = try file.readToEndAlloc(allocator, std.math.maxInt(usize));
        defer allocator.free(content);

        var line_iter = mem.splitScalar(u8, content, '\n');
        const num_dims_line = line_iter.next() orelse return error.InvalidFile;
        const shape_line = line_iter.next() orelse return error.InvalidFile;
        const dtype_line = line_iter.next() orelse return error.InvalidFile;

        const num_dims = try std.fmt.parseInt(usize, std.mem.trim(u8, num_dims_line, " \t\r"), 10);
        var shape_list = ArrayList(usize).init(allocator);
        defer shape_list.deinit();

        var dims_iter = mem.splitScalar(u8, shape_line, ' ');
        while (dims_iter.next()) |tok| {
            const t = std.mem.trim(u8, tok, " \t\r");
            if (t.len == 0) continue;
            const dim = try std.fmt.parseInt(usize, t, 10);
            try shape_list.append(dim);
        }
        if (shape_list.items.len != num_dims) return error.InvalidShape;

        const dtype_trim = std.mem.trim(u8, dtype_line, " \t\r");
        const dtype_int = try std.fmt.parseInt(usize, dtype_trim, 10);
        const fields = @typeInfo(DType).Enum.fields;
        if (dtype_int >= fields.len) return error.InvalidDType;
        const dtype = @as(DType, @enumFromInt(dtype_int));

        const elems = Tensor.totalElements(shape_list.items);
        const width: usize = if (dtype == .c64) 2 else 1;
        const expected = elems * width;

        var values = ArrayList(f64).init(allocator);
        defer values.deinit();

        while (line_iter.next()) |data_line| {
            var tok_iter = mem.splitScalar(u8, data_line, ' ');
            while (tok_iter.next()) |tok| {
                const t = std.mem.trim(u8, tok, " \t\r");
                if (t.len == 0) continue;
                const v = try std.fmt.parseFloat(f64, t);
                try values.append(v);
            }
        }
        if (values.items.len < expected) return error.InvalidFile;

        var data = try allocator.alloc(f64, expected);
        @memcpy(data[0..expected], values.items[0..expected]);

        const shape_copy = try allocator.dupe(usize, shape_list.items);
        var strides = try allocator.alloc(usize, shape_copy.len);
        if (shape_copy.len > 0) {
            strides[shape_copy.len - 1] = 1;
            var i: usize = shape_copy.len;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * shape_copy[i];
            }
        }

        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = dtype,
            .offset = 0,
            .is_view = false,
        };
    }
};

fn isPowerOfTwo(n: usize) bool {
    return n != 0 and (n & (n - 1)) == 0;
}

fn bitReverse(x: usize, bits: usize) usize {
    var v = x;
    var r: usize = 0;
    var i: usize = 0;
    while (i < bits) : (i += 1) {
        r = (r << 1) | (v & 1);
        v >>= 1;
    }
    return r;
}

